      guidePitch2: 'Toon de flyer: de vergelijking 28 € / 36 € spreekt voor zich.',
      guidePitch3: 'Eerst de gratis versie (tafelreserveringen, € 0): niemand zegt nee tegen gratis. Afhaal en levering: € 20/maand, eerste maand gratis, en 0% op wat ter plaatse betaald wordt.',
      guidePitch4: 'Terminal gratis voor de eerste 50 restaurants ingeschreven vóór 5 oktober, daarna waarborg van 80 €: dat is het argument om nu te tekenen.',
      guideTechTitle: 'Technieken die werken',
      guideTech1: 'Stel vragen vóór je verkoopt: « Zit u op Uber Eats? Wat kost u dat per maand? » De handelaar overtuigt zichzelf.',
      guideTech2: 'Praat over zijn geld, niet over onze functies: + 8 € per bestelling, 800 € per maand bij 100 bestellingen.',
      guideTech3: 'Schrijf hem ter plaatse in, samen, in 5 minuten: account aangemaakt = je premie van 20 € verworven. Koppel daarna je fiche aan de zaak in Sales.',
      guideTech4: 'Zijn kaart? Hij hoeft niets te doen: Fairide maakt ze op basis van zijn website, Uber Eats of een foto van de kaart. Zeg het duidelijk.',
      guideTech5: 'Noteer alles in Sales zodra je buiten bent: fase, wat hij zei, wanneer hij weer beschikbaar is. Een niet-genoteerd bezoek is een verloren bezoek.',
      guideTech6: 'Een niet-getekende « ja » bestaat niet: leg een precieze afspraak vast (« donderdag 15 uur, ik kom terug met de terminal? »).',
      guideNoTitle: 'Is het nee? Geen probleem',
      guideNo1: 'We blijven professioneel en vriendelijk: « Geen probleem, bedankt voor uw tijd. »',
      guideNo2: 'We laten de flyer op de toonbank: « Ik laat hem hier, alles staat erop, met ons nummer. »',
      guideNo3: 'We wensen een prettige dag, en gaan buiten.',
      guideNo4: 'In Sales: fase « Later », een nota over de reden van de nee, en een volgende actie de week erna.',
      guideNo5: 'We komen de week erna terug, zonder aan te dringen: « Ik was in de buurt, hebt u er al over kunnen nadenken? » Veel « nee » wordt « ja » bij het tweede bezoek.',
      guideYesTitle: 'Is het ja?',
      guideYes1: 'Maak het account samen ter plaatse aan (fairide.be › Inschrijven › Restaurant): e-mail, telefoon, adres.',
      guideYes2: 'Leg de drie data uit: app op 6 oktober, reservaties en afhaling op de 10e, levering op de 20e.',
      guideYes3: 'Zeg wat er daarna gebeurt: Fairide maakt zijn kaart, hij controleert ze, het team valideert hem, dan wordt de terminal in 30 minuten samen geïnstalleerd.',
      guideYes4: 'Koppel je fiche aan de zaak in Sales en zet ze op « Ingeschreven op Fairide »: je premie wordt geteld.',
