      terminalCardIntro: 'Alles gebeurt op de terminal die Fairide levert, een alles-in-één-toestel, hetzelfde soort apparaat als bij Uber Eats, Takeaway of Deliveroo. Niets te installeren of in te stellen: we stellen hem samen met jou in bij de overhandiging.',
      terminalCard1: 'Elke bestelling (levering, afhaling, online betaling) en elke reservatie komt er live op binnen, met een geluid.',
