      printerTitle: 'Bonnenprinter',
      printerStatusNone: 'Geen printer verbonden',
      printerStatusUnsupported: 'Bluetooth hier niet beschikbaar',
      autoPrintOn: 'Auto-print',
      printerHelp: 'Je gebruikt Fairide in de app op je tablet, telefoon of pc: vanuit die app wordt het ticket afgedrukt. Zet je Bluetooth-thermische printer aan en koppel ze hier één keer per dienst: elk ticket vertrekt dan met één klik, of automatisch bij elke nieuwe bestelling. Sluit en heropen je de app, koppel dan opnieuw (één klik).',
      printerConnect: '🔗 Mijn printer verbinden',
      printerTest: 'Testbon printen',
      printerDisconnect: 'Verbinding verbreken',
      autoPrint: 'Elke nieuwe bestelling automatisch printen',
      autoPrintHelp: 'Zodra een betaalde bestelling binnenkomt, komt het bonnetje uit de verbonden printer, zonder iets aan te raken. Houd dit tabblad open tijdens de dienst.',
      printerCompatTitle: 'Welke printer?',
      printerCompat1: 'ESC/POS-thermische printer met Bluetooth Low Energy (BLE), papier 58 of 80 mm: bv. Xprinter, Munbyn, Goojprt, Netum, Phomemo (“BLE”-modellen). Een klassiek Bluetooth-model (SPP) is niet zichtbaar vanuit een browser.',
      printerCompat2: 'Vanuit de Fairide-app op Android (tablet of telefoon), op Windows-pc, Mac of Chromebook: rechtstreeks Bluetooth naar de printer. Op iPad en iPhone heeft de app geen Bluetooth-toegang: gebruik “Leveringsbon afdrukken”, via AirPrint of een wifi-printer.',
      printerCompat3: 'USB-, wifi- of netwerkprinter (Epson, Star…): installeer ze op het toestel zoals elke printer; “Leveringsbon afdrukken” gebruikt dan het afdrukvenster van het toestel. Op Android kan de gratis app RawBT het ticket ook doorsturen.',
