      newTicketHelp: 'Telefonische bestelling, tafel ter plaatse, vrije keukenbon.',
      appStepsTitle: 'Afdrukken vanuit de app, op dit toestel',
      appInstalled: 'Je zit in de geïnstalleerde Fairide-app: afdrukken werkt zoals hieronder beschreven.',
      appInstallHint_android: 'Tip: installeer de app voor de dienst. In Chrome: menu ⋮ → “App installeren” (of “Toevoegen aan startscherm”). Ze opent dan op volledig scherm, als een app.',
      appInstallHint_ios: 'Tip: installeer de app voor de dienst. In Safari: knop Delen → “Zet op beginscherm”. Ze opent dan op volledig scherm, als een app.',
      appInstallHint_desktop: 'Tip: installeer de app voor de dienst. In Chrome of Edge: pictogram “Installeren” rechts in de adresbalk (of menu → “Fairide installeren”). Ze opent dan in een eigen venster.',
      appSteps_android_1: 'Zet de Bluetooth-thermische printer (BLE) aan en schakel Bluetooth in op de tablet of telefoon.',
      appSteps_android_2: 'Tik op “Mijn printer koppelen”, kies ze in de lijst en druk een testticket af. Vink “Automatisch afdrukken” aan zodat elke nieuwe bestelling vanzelf afdrukt.',
      appSteps_android_3: 'Hou tijdens de dienst de app open op Bestellingen. Sluit je ze, koppel de printer dan met één klik opnieuw. Zonder thermische printer: “Leveringsbon afdrukken” stuurt het ticket naar elke wifi-printer op het toestel (of via de app RawBT).',
      appSteps_ios_1: 'Op iPhone en iPad heeft de web-app geen Bluetooth-toegang (beperking van Apple). Vanaf 6 oktober 2026 drukt de echte Fairide-app uit de App Store rechtstreeks via Bluetooth af; tot dan twee opties:',
      appSteps_ios_2: 'Open een bestelling en tik op “Leveringsbon afdrukken”: het afdrukvenster van Apple toont elke AirPrint- of wifi-printer op het netwerk (Epson, Star, Brother…). Kies ze één keer, ze blijft voorgesteld.',
      appSteps_ios_3: 'Voor een echte thermische ticketprinter aan de toonbank: hou een Android-tablet (ook een instapmodel) gekoppeld via Bluetooth. Ze drukt elke bestelling automatisch af terwijl je de rest op iPhone beheert.',
      appSteps_desktop_1: 'Zet de Bluetooth-thermische printer (BLE) aan en controleer of Bluetooth op de computer aanstaat (Chrome of Edge vereist).',
      appSteps_desktop_2: 'Klik op “Mijn printer koppelen”, kies ze in de lijst en druk een testticket af. Vink “Automatisch afdrukken” aan zodat elke nieuwe bestelling vanzelf afdrukt.',
      appSteps_desktop_3: 'USB- of netwerkprinter (Epson, Star…) al geïnstalleerd op de pc: “Leveringsbon afdrukken” gebruikt ze via het gewone afdrukvenster. Hou de app open op Bestellingen tijdens de dienst.',
      appNativeSoon: '📲 De echte Fairide-app (App Store en Google Play) komt op 6 oktober 2026: ze drukt via Bluetooth af op elk toestel, ook iPhone en iPad. Tot dan gebruik je de web-app die je vanuit de browser installeert; de stappen hieronder gelden.',
